        case extraFraction = "extra_fraction"
        case extraPoints = "extra_points"
        case findings = "findings"
        case modelBboxMm = "model_bbox_mm"
        case notSeen = "not_seen"
        case notVisible = "not_visible"
        case ok = "ok"
        case partly = "partly"
        case parts = "parts"
        case pointsUsed = "points_used"
        case scan = "scan"
