    public let planID: String
    public let qtyNeeded: Int?
    public let quoteID: String
    /// Name of the deterministic rule applied, e.g. 'eligible, then exact_mpn before equivalent
    /// before substitute, then lowest total within cap, then shortest lead'. Versioned in code.
